  @override
  String accountsSyncImportPreviewSummary(int profiles, int accounts) {
    String _temp0 = intl.Intl.pluralLogic(
      profiles,
      locale: localeName,
      other: '$profiles پروفایل',
      one: '1 پروفایل',
      zero: '0 پروفایل',
    );
    String _temp1 = intl.Intl.pluralLogic(
      accounts,
      locale: localeName,
      other: '$accounts حساب',
      one: '1 حساب',
      zero: '0 حساب',
    );
    return '$_temp0 • $_temp1';
  }

